WITH unpacked AS (SELECT id, service, level, latency_ms, status_code, context['version'] AS version, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version, COALESCE(context['version'], 'unknown') AS version_or_default, COALESCE(context['trace'], 'direct') AS trace_or_default, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count FROM app_logs WHERE level = 'WARN') SELECT *, DENSE_RANK() OVER (PARTITION BY service ORDER BY status_code DESC) AS status_code_dense_rank, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY service, level), 4) AS latency_ms_share, RANK() OVER w_hist AS status_code_rank FROM unpacked WINDOW w_hist AS (PARTITION BY level ORDER BY status_code)
